```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.List;

public class CommandExecutor {
    public void pingHost(String hostname) throws Exception {
        // To fix this, we use ProcessBuilder and pass the command and arguments 
        // as a List of strings. This ensures that the shell does not interpret 
        // special characters (like ';' or '&') as command separators.
        ProcessBuilder processBuilder = new ProcessBuilder("ping", "-c", "1", hostname);

        // Start the process safely
        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
    }
}
```

